'use strict';
const gymNow=()=>window.GymRemote?.active?window.GymRemote.now():Date.now();
const M=GymModel,KEY='courtside-v1',screen=document.querySelector('#screen'),controls=document.querySelector('#controls');
let state=M.defaults(),undo=[],channel=null,audioContext=null,lastAlarm=null,wake=null,keepAwake=false,revision=0;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved){state=M.normalize(saved.state);revision=saved.revision||0;}}catch{}
try{channel=new BroadcastChannel(KEY);channel.onmessage=e=>receive(e.data);}catch{}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(message){document.querySelector('#notice').textContent=message;clearTimeout(notify.timeout);notify.timeout=setTimeout(()=>document.querySelector('#notice').textContent='',4500);}
function save(){if(window.GymRemote?.active){window.GymRemote.push(state);return;}revision=Math.max(Date.now(),revision+1);const message={state,revision};try{localStorage.setItem(KEY,JSON.stringify(message));}catch{notify('Storage unavailable. Keep this page open to retain your scores.');}channel?.postMessage(message);}
function receive(message){if(window.GymRemote?.active)return;if(!message||message.revision<=revision)return;revision=message.revision;state=M.normalize(message.state);undo=[];render();}
addEventListener('storage',e=>{if(e.key===KEY&&e.newValue)try{receive(JSON.parse(e.newValue));}catch{}});
function mutate(fn,remember=false){if(window.GymRemote?.active&&!window.GymRemote.canEdit){notify('Use the paired phone remote to change the display.');return;}if(remember){undo.push(JSON.stringify(state.courts));if(undo.length>30)undo.shift();}fn();save();render();}
function courtMarkup(c,i){return `<article class="court"><div class="court-top"><span>${esc(c.name)}</span><span>VOLLEYBALL <b>•</b> LIVE</span></div><div class="teams">${c.teams.map((t,j)=>`<div class="team team-${j}"><div class="team-name">${esc(t.name)}</div><div class="score-number ${t.score>99?'triple':''}">${t.score}</div><div class="set-display"><span>SETS</span> ${t.sets} <span class="serve ${c.serve===j?'serving':''}">${c.serve===j?'● SERVE':'—'}</span></div></div>`).join('')}</div><div class="court-bottom"><span>PLAY THE NEXT POINT.</span><span>COURTSIDE <b>↗</b></span></div></article>`;}
function teamControls(c,i,j){const t=c.teams[j];return `<div class="team-editor team-${j}"><label class="field-label" for="team-${i}-${j}">${j===0?'NAVY SIDE':'RED SIDE'}</label><input id="team-${i}-${j}" data-name="${i},${j}" maxlength="24" value="${esc(t.name)}" aria-label="Court ${i+1}, team ${j+1} name"><div class="score-actions"><button data-action="point" data-court="${i}" data-team="${j}" data-delta="-1" aria-label="Subtract point from ${esc(t.name)}">−</button><button class="add-point" data-action="point" data-court="${i}" data-team="${j}" data-delta="1">+1 point</button></div><div class="set-controls"><span>Sets</span><button data-action="set" data-court="${i}" data-team="${j}" data-delta="-1" aria-label="Subtract set from ${esc(t.name)}">−</button><strong>${t.sets}</strong><button data-action="set" data-court="${i}" data-team="${j}" data-delta="1" aria-label="Add set to ${esc(t.name)}">+</button><button class="serve-control" data-action="serve" data-court="${i}" data-team="${j}" aria-pressed="${c.serve===j}">● Serve</button></div></div>`;}
function render(){document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('selected',b.dataset.mode===state.mode);b.setAttribute('aria-pressed',String(b.dataset.mode===state.mode));});screen.className=`screen ${state.mode}-mode`;
 if(state.mode==='clock'){screen.innerHTML='<div class="clock-face"><p class="eyebrow">RIGHT HERE. RIGHT NOW.</p><div id="clock-time"></div><div id="clock-date"></div></div><div class="screen-signature">COURTSIDE / GYM DISPLAY</div>';controls.innerHTML=`<div class="simple-controls"><div><h2>Gym clock</h2><p>Your device’s local time.</p></div><label class="toggle"><input id="hour24" type="checkbox" ${state.hour24?'checked':''}>24-hour time</label></div>`;}
 else if(state.mode==='timer'){screen.innerHTML='<div class="timer-face"><p id="timer-status" class="eyebrow"></p><div id="timer-time"></div><div id="timer-caption"></div></div><div class="screen-signature">COURTSIDE / PRACTICE TIMER</div>';controls.innerHTML=`<div class="timer-controls"><div class="presets"><span class="field-label">QUICK SET</span>${[1,3,5,10,15].map(n=>`<button data-minutes="${n}">${n} min</button>`).join('')}</div><form id="duration-form"><label>Minutes<input id="minutes" type="number" min="0" max="99" value="${Math.floor(state.duration/60000)}" required></label><span>:</span><label>Seconds<input id="seconds" type="number" min="0" max="59" value="${Math.floor(state.duration/1000)%60}" required></label><button type="submit">Set timer</button></form><div class="timer-actions"><button id="start-pause" class="primary">${M.remaining(state,gymNow())===0?'Restart timer':state.deadline===null?'Start timer':'Pause timer'}</button><button id="reset-timer">Reset</button><label class="toggle"><input id="sound" type="checkbox" ${state.sound?'checked':''}>Sound at end</label></div></div>`;}
 else {const count=state.mode==='dual'?2:1;screen.innerHTML=state.courts.slice(0,count).map(courtMarkup).join('');controls.innerHTML=`<div class="controls-title"><div><h2>Keep the game moving.</h2><p>Tap a point. We’ll take care of the big screen.</p></div><button id="undo" ${undo.length?'':'disabled'}>↶ Undo point</button></div><div class="court-editors ${count===2?'two-editors':''}">${state.courts.slice(0,count).map((c,i)=>`<div class="court-editor"><div class="editor-heading"><label class="court-name-label">Court name<input data-court-name="${i}" maxlength="30" value="${esc(c.name)}" aria-label="Court ${i+1} name"></label><div><button data-action="swap" data-court="${i}" class="text-button">⇄ Swap ends</button><button data-action="reset" data-court="${i}" class="text-button">Reset</button></div></div><div class="team-editors">${teamControls(c,i,0)}${teamControls(c,i,1)}</div></div>`).join('')}</div>`;}
 tick();document.dispatchEvent(new Event('gym-render'));}
function tick(){if(state.mode==='clock'){const now=new Date();const parts=new Intl.DateTimeFormat(undefined,{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:!state.hour24}).formatToParts(now);document.querySelector('#clock-time').innerHTML=parts.map(p=>p.type==='dayPeriod'?`<small>${esc(p.value)}</small>`:esc(p.value)).join('');document.querySelector('#clock-date').textContent=now.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});}
 const left=M.remaining(state,gymNow());if(state.mode==='timer'){document.querySelector('#timer-time').textContent=M.format(left);document.querySelector('#timer-status').textContent=left===0?'TIME’S UP':state.deadline!==null?'EVERY SECOND COUNTS.':left===state.duration?'READY WHEN YOU ARE.':'TAKE A BREATH.';document.querySelector('#timer-caption').textContent=left===0?'Great work. Reset for the next round.':state.deadline!==null?'IN PROGRESS':left===state.duration?'PRACTICE TIMER':'PAUSED';if(!window.GymRemote?.active)document.querySelector('#timer-caption').textContent='Duration '+M.format(state.duration)+' · tap to edit';screen.classList.toggle('time-up',left===0);}
 if(state.deadline!==null&&left===0&&lastAlarm!==state.deadline){lastAlarm=state.deadline;const restartButton=document.querySelector('#start-pause');if(restartButton)restartButton.textContent='Restart timer';if(state.sound)beep();}}
function setDuration(ms){mutate(()=>{state.duration=ms;state.remaining=ms;state.deadline=null;});lastAlarm=null;}
function toggleTimer(){if(M.remaining(state,gymNow())<=0){if(state.duration<=0){notify('Set a duration greater than zero.');return;}mutate(()=>{state.remaining=state.duration;state.deadline=gymNow()+state.duration;});return;}if(state.deadline!==null){mutate(()=>{state.remaining=M.remaining(state,gymNow());state.deadline=null;});}else{if(M.remaining(state,gymNow())<=0)state.remaining=state.duration;if(state.remaining<=0){notify('Set a duration greater than zero.');return;}mutate(()=>state.deadline=gymNow()+state.remaining);}}
function initAudio(){try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();}catch{notify('Sound is unavailable in this browser. The visual alarm will still work.');}}
function beep(){if(!audioContext||audioContext.state!=='running')return;for(let i=0;i<3;i++){const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime+i*.35;o.frequency.value=740;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.22,t+.02);g.gain.exponentialRampToValueAtTime(.001,t+.22);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+.25);}}
controls.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.minutes){setDuration(Number(b.dataset.minutes)*60000);return;}if(b.id==='start-pause'){if(state.sound)initAudio();toggleTimer();return;}if(b.id==='reset-timer'){setDuration(state.duration);return;}if(b.id==='undo'){if(undo.length){state.courts=JSON.parse(undo.pop());save();render();}return;}const a=b.dataset.action;if(!a)return;const i=Number(b.dataset.court),j=Number(b.dataset.team),c=state.courts[i];if(a==='reset'&&!confirm(`Reset points and sets for ${c.name}? Team names will stay.`))return;mutate(()=>{if(a==='point'||a==='set'){const key=a==='point'?'score':'sets';c.teams[j][key]=Math.max(0,Math.min(key==='score'?999:99,c.teams[j][key]+Number(b.dataset.delta)));}if(a==='serve')c.serve=j;if(a==='swap'){c.teams.reverse();c.serve=1-c.serve;}if(a==='reset'){c.teams.forEach(t=>{t.score=0;t.sets=0;});c.serve=0;}},a!=='serve');});
controls.addEventListener('change',e=>{const el=e.target;if(el.dataset.name){const [i,j]=el.dataset.name.split(',').map(Number);mutate(()=>state.courts[i].teams[j].name=el.value.trim()|| (j===0?'HOME':'AWAY'));}if(el.dataset.courtName!==undefined)mutate(()=>state.courts[Number(el.dataset.courtName)].name=el.value.trim()||'COURT');if(el.id==='hour24')mutate(()=>state.hour24=el.checked);if(el.id==='sound'){state.sound=el.checked;if(el.checked)initAudio();save();}});
controls.addEventListener('submit',e=>{if(e.target.id!=='duration-form')return;e.preventDefault();const min=Number(document.querySelector('#minutes').value),sec=Number(document.querySelector('#seconds').value);if(!Number.isInteger(min)||!Number.isInteger(sec)||min<0||min>99||sec<0||sec>59)return;const ms=(min*60+sec)*1000;if(!ms){notify('Set a duration greater than zero.');return;}setDuration(ms);});
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>mutate(()=>state.mode=b.dataset.mode)));
async function setDisplay(on){document.body.classList.toggle('display-only',on);document.querySelector('#exit-display').hidden=!on;if(on){if(document.documentElement.requestFullscreen)try{await document.documentElement.requestFullscreen();}catch{notify(window.GymRemote?.active?'TV display ready. Full screen is optional.':'Clean display enabled. Use your device’s screen mirroring to show it on TV.');}if(keepAwake)requestWake();}else if(document.fullscreenElement)try{await document.exitFullscreen();}catch{}}
document.querySelector('#display').onclick=()=>setDisplay(true);document.querySelector('#exit-display').onclick=()=>setDisplay(false);
document.querySelector('#window').onclick=()=>{const url=new URL(location.href);url.searchParams.set('display','1');const opened=window.open(url.href,'courtside-display');if(!opened)notify('Allow pop-ups to open a separate display window.');};
document.querySelector('#help').onclick=()=>document.querySelector('#help-dialog').showModal();document.querySelector('#close-help').onclick=()=>document.querySelector('#help-dialog').close();
async function requestWake(){if(!keepAwake||document.visibilityState!=='visible'||wake)return;try{wake=await navigator.wakeLock.request('screen');wake.addEventListener('release',()=>wake=null);}catch{notify('Screen wake lock unavailable. Adjust your device’s auto-lock setting.');}}
document.querySelector('#awake').onchange=async e=>{keepAwake=e.target.checked;if(keepAwake)await requestWake();else {await wake?.release();wake=null;}};document.addEventListener('visibilitychange',()=>{if(keepAwake&&document.visibilityState==='visible')requestWake();tick();});
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,button,[contenteditable="true"]')||document.querySelector('dialog[open]'))return;if(e.key===' '&&state.mode==='timer'){e.preventDefault();if(state.sound)initAudio();toggleTimer();}if(e.key.toLowerCase()==='f')setDisplay(!document.body.classList.contains('display-only'));if(e.key==='Escape')setDisplay(false);});
const requestedMode=new URLSearchParams(location.search).get('mode');if(['clock','timer','score','dual'].includes(requestedMode))state.mode=requestedMode;
render();if(new URLSearchParams(location.search).get('display')==='1'){document.body.classList.add('display-only');document.querySelector('#exit-display').hidden=false;}setInterval(tick,200);


